window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-06e43b28dd4b5b26"]={"versions": [{"id": "FIG-06e43b28dd4b5b26", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can : CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26 : FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame : CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering : PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame : CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping : PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu : SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu : SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering : PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering : PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu : SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering : PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu : ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu : ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-5f3c28e2a1fde592", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-510b8ab49f8eabfd", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-b68f14581375d520", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-617d9ea9c71042c2", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-17f8a28859c4e0e8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}, {"id": "FIG-8852c2c1e0a92b2b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm / Instanzdiagramm (AUTOSAR M1-Systemmodellinstanz basierend auf dem Metamodell M2).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (System Template, <code>AUTOSAR_TPS_SystemTemplate</code>, R4.3.1), Kapitel <em>Secure Onboard Communication (SecOC)</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Exemplarische Modellierung der kombinierten Übertragung (<em>Combined / Single-PDU Transmission</em>) einer gesicherten Botschaft über CAN. Bei <code>useAsCryptographicIPdu = false</code> werden die authentische Nutzlast (<code>authenticPdu</code>) und die kryptografischen Daten (Authenticator/MAC sowie Freshness Value) in einer einzigen logischen <code>SecuredIPdu</code> zusammengefasst und in einem gemeinsamen Frame übertragen (im Gegensatz zur getrennten Übertragung via Split-PDU bei <code>useAsCryptographicIPdu = true</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Dargestellte Instanzen & Metaklassen</p>\n<ul class=\"fig-list\">\n<li><code>Can: CanPhysicalChannel</code></li>\n<li>Metaklasse: <code>CanPhysicalChannel</code> (Spezialisierung von <code>PhysicalChannel</code>).</li>\n<li>Container-Rolle: Aggregiert via Komposition alle PDU- und Frame-Triggerings des physischen CAN-Busses.</li>\n<li><code>Frame_Id26: FrameTriggering</code></li>\n<li>Metaklasse: <code>FrameTriggering</code>.</li>\n<li>Verknüpft den CAN-Frame mit dem Kommunikationskanal (Festlegung der Bus-spezifischen Übertragungsparameter, z. B. CAN-ID 0x26).</li>\n<li>Assoziationen:</li>\n<li><code>+frame</code> $\\rightarrow$ <code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li><code>+pduTriggering</code> $\\rightarrow$ <code>cryptographicPduTriggering: PduTriggering</code></li>\n<li><code>CryptoAndAuthenticFrame: CanFrame</code></li>\n<li>Metaklasse: <code>CanFrame</code> (Spezialisierung von <code>Frame</code>).</li>\n<li>Repräsentiert die L2-Übertragungseinheit (CAN-Data-Link-Layer).</li>\n<li>Aggregiert per Komposition (<code>+pduToFrameMapping</code>) die Instanz <code>cryptographicPduMapping</code>.</li>\n<li><code>cryptographicPduMapping: PduToFrameMapping</code></li>\n<li>Metaklasse: <code>PduToFrameMapping</code>.</li>\n<li>Spezifiziert das Bit-/Byte-Packing der <code>SecuredIPdu</code> in den CAN-Frame (Startposition, Endianness, Länge).</li>\n<li>Assoziation: <code>+pdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li><code>CryptographicPdu: SecuredIPdu</code></li>\n<li>Metaklasse: <code>SecuredIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Zustand/Attribut: <code>useAsCryptographicIPdu = false</code>.</li>\n<li>Funktion: Fasst Nutzdaten und Authentifizierungsdaten zusammen.</li>\n<li>Assoziation: <code>+payload</code> $\\rightarrow$ <code>authenticPduTriggering: PduTriggering</code>.</li>\n<li><code>cryptographicPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>CryptographicPdu: SecuredIPdu</code>.</li>\n<li>Dient als Vermittlungsinstanz zwischen <code>FrameTriggering</code> und der <code>SecuredIPdu</code>.</li>\n<li><code>authenticPduTriggering: PduTriggering</code></li>\n<li>Metaklasse: <code>PduTriggering</code>.</li>\n<li>Durch <code>CanPhysicalChannel</code> komponiert.</li>\n<li>Assoziation: <code>+iPdu</code> $\\rightarrow$ <code>authenticPdu: ISignalIPdu</code>.</li>\n<li><strong>Architekturmerkmal:</strong> Besitzt keine Assoziation zu einem <code>FrameTriggering</code>; die Anbindung an den Bus erfolgt ausschließlich indirekt über die Referenz <code>SecuredIPdu.payload</code>.</li>\n<li><code>authenticPdu: ISignalIPdu</code></li>\n<li>Metaklasse: <code>ISignalIPdu</code> (erbt von <code>IPdu</code>).</li>\n<li>Repräsentiert die ungesicherte Original-I-PDU aus dem COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus der Modellkonfiguration leitet sich zur Laufzeit folgende BSW-Interaktion ab:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Com]             [PduR]            [SecOC]             [CryIf/CSM]          [CanIf]</p>\n<p class=\"fig-p\">|                 |                  |                     |                  |</p>\n<p class=\"fig-p\">|-- Com_SendPdu ->|                  |                     |                  |</p>\n<p class=\"fig-p\">|   (authentic)   |-- PduR_Transmit->|                     |                  |</p>\n<p class=\"fig-p\">|                 |                  |-- Csm_MacGenerate ->|                  |</p>\n<p class=\"fig-p\">|                 |                  |<-- MAC + Freshness -|                  |</p>\n<p class=\"fig-p\">|                 |                  | (Assemble SecuredIPdu:                 |</p>\n<p class=\"fig-p\">|                 |                  |  Payload + Header/MAC)                 |</p>\n<p class=\"fig-p\">|                 |                  |-- PduR_Transmit --->|                  |</p>\n<p class=\"fig-p\">|                 |                  |   (SecuredIPdu)     |-- CanIf_Transmit |</p>\n<p class=\"fig-p\">|                 |                  |                     |   (Frame 0x26) ->|</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>TX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> übergibt die <code>authenticPdu</code> an den <code>PduR</code>.</li>\n<li><code>PduR</code> leitet die PDU an das Modul <code>SecOC</code> weiter (<code>SecOC_Transmit</code>).</li>\n<li><code>SecOC</code> ruft den <code>CSM</code> (Crypto Service Manager) zur MAC-Generierung auf und holt den Freshness-Zählerwert (über BswM/FVM).</li>\n<li><code>SecOC</code> baut die <code>SecuredIPdu</code> zusammen (Payload der <code>authenticPdu</code> + optionaler Truncated Freshness Value + Truncated MAC).</li>\n<li>Da <code>useAsCryptographicIPdu = false</code> gilt, wird die gesamte assemblierte <code>SecuredIPdu</code> über den <code>PduR</code> direkt an das <code>CanIf</code> übergeben und in <code>CryptoAndAuthenticFrame</code> (ID 0x26) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>RX-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> empfängt Frame 0x26 und signalisiert via <code>PduR</code> an <code>SecOC</code> (<code>SecOC_RxIndication</code>).</li>\n<li><code>SecOC</code> trennt Payload von den Authentifizierungsdaten, verifiziert den MAC via CSM.</li>\n<li>Bei Erfolg: <code>SecOC</code> leitet die <code>authenticPdu</code> via <code>PduR</code> an <code>Com</code> weiter.</li>\n<li>Bei Verifikation-Fehlschlag: PDU wird verworfen, Meldung an DEM/DET (<code>SECOC_E_CRYPTO_FAILURE</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität (TPS_SYST_02173 & RS_SYST_00054):</strong></li>\n<li>Wenn <code>useAsCryptographicIPdu == false</code>, darf die <code>authenticPduTriggering</code> <strong>niemals</strong> direkt von einer <code>FrameTriggering</code>-Instanz referenziert werden.</li>\n<li>Das ARXML-Modell muss zwingend <code>SecuredIPdu.payload</code> auf die <code>PduTriggering</code> der <code>authenticPdu</code> setzen.</li>\n<li><strong>PduR- & Stack-Konfiguration:</strong></li>\n<li><code>authenticPdu</code> existiert auf dem Bus physisch nicht als eigenständiges Signal-/Frame-Gebilde. Im BSW-Generat darf kein direkter Übertragungspfad <code>PduR -&gt; CanIf</code> für die <code>authenticPdu</code> konfiguriert werden; sie verbleibt stack-intern zwischen <code>Com</code> und <code>SecOC</code>.</li>\n<li>Nur die <code>SecuredIPdu</code> erhält ein Mapping auf den CanIf-TX-Puffer bzw. die Hardware-Mailbox.</li>\n<li><strong>Payload- & Bandbreiten-Budgetierung (Classic CAN vs. CAN-FD):</strong></li>\n<li>Da Nutzdaten, Freshness-Bits und MAC-Bits gemeinsam in die PDU gepackt werden, reduziert sich die verfügbare Nutzlast.</li>\n<li>Bei Classic CAN (max. 8 Byte Payload): Bei einem 3-Byte-MAC und 1-Byte-Freshness verbleiben maximal 4 Byte für die <code>authenticPdu</code>. Reicht dies nicht aus, muss zwingend entweder CAN-FD genutzt oder auf das Split-PDU-Verfahren (<code>useAsCryptographicIPdu = true</code>) umgestellt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-06e43b28dd4b5b26", "to": "FIG-5f3c28e2a1fde592", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>CryptographicPdu :SecuredIPdu</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>CryptographicPdu: SecuredIPdu</code>).</li>\n<li><code>authenticPdu :ISignalIPdu</code>: Leerzeichen nach dem Doppelpunkt ergänzt (<code>authenticPdu: ISignalIPdu</code>).</li>\n<li><code>CryptoAndAuthenticFrame : CanFrame</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>CryptoAndAuthenticFrame: CanFrame</code>).</li>\n<li><code>Frame_Id26 : FrameTriggering</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>Frame_Id26: FrameTriggering</code>).</li>\n<li><code>cryptographicPduMapping : PduToFrameMapping</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>cryptographicPduMapping: PduToFrameMapping</code>).</li>\n<li><code>authenticPduTriggering : PduTriggering</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>authenticPduTriggering: PduTriggering</code>).</li>\n<li><code>cryptographicPduTriggering : PduTriggering</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>cryptographicPduTriggering: PduTriggering</code>).</li>\n<li><code>Can : CanPhysicalChannel</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>Can: CanPhysicalChannel</code>).</li>\n</ul>"}, {"from": "FIG-5f3c28e2a1fde592", "to": "FIG-510b8ab49f8eabfd", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-510b8ab49f8eabfd", "to": "FIG-b68f14581375d520", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b68f14581375d520", "to": "FIG-617d9ea9c71042c2", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-617d9ea9c71042c2", "to": "FIG-17f8a28859c4e0e8", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-17f8a28859c4e0e8", "to": "FIG-8852c2c1e0a92b2b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
